    # TODO: call fn() up to retries times; return result; re-raise last exception
    pass

lessons.solution_code:
def retry_call(fn, retries=3):
    last = None
    for _ in range(retries):
        try:
            return fn()
        except Exception as exc:
            last = exc
    raise last

tests.unittest_code:
def test_retry_success(self):
    calls = {'n': 0}
    def flaky():
        calls['n'] += 1
        if calls['n'] < 3:
            raise ValueError('fail')
        return 'ok'
    self.assertEqual(retry_call(flaky, retries=3), 'ok')
    self.assertEqual(calls['n'], 3)

def test_retry_exhaust(self):
    def always():
        raise RuntimeError('boom')
    with self.assertRaises(RuntimeError):
        retry_call(always, retries=2)

